from decimal import Decimal, InvalidOperation


def split_installments(total: str, n: int) -> list[Decimal]:
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError('n must be an integer >= 1')
    if n < 1:
        raise ValueError('n must be an integer >= 1')
    if not isinstance(total, str):
        raise ValueError('total must be a decimal string')
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid total') from None
    if not amount.is_finite():
        raise ValueError('total must be finite')
    if amount < 0:
        raise ValueError('total must be >= 0')
    if amount.as_tuple().exponent < -2:
        raise ValueError('total must have at most 2 decimal places')
    _sign, digits, exponent = amount.as_tuple()
    digits_int = 0
    for digit in digits:
        digits_int = digits_int * 10 + digit
    total_cents = digits_int * (10 ** (exponent + 2))
    base, remainder = divmod(total_cents, n)
    result = []
    for i in range(n):
        cents = base + (1 if i < remainder else 0)
        result.append(Decimal(f'{cents // 100}.{cents % 100:02d}'))
    return result
